export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/hb3
rm -rf $D; mkdir -p $D; cd $D || exit 1
cat > p.b64 <<'EOS'

EOS
base64 -d p.b64 > p.zip && unzip -oq p.zip -d $D
for t in h00 h01 h02 h03 h04 h05 h06 h07 h08 h09 h10 h11; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1
  if grep -q "DONE_$t" $t.log; then echo "OK $t $(grep -o 'CK_BUFHCLK[0-9]*' $t.pips | head -1)"; else echo "FAIL $t $(grep -m1 ERROR $t.log)"; fi
done
tar czf /tmp/hb3_out.tgz *.bit *.pips 2>/dev/null || true
echo HB3DONE
